package com.taylordproductivty.med_timing_tracker.data

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.Query
import kotlinx.coroutines.flow.Flow

@Dao
interface DoseLogDao {
    @Query(
        "SELECT * FROM dose_logs WHERE profileId = :profileId ORDER BY givenAtEpochMillis DESC LIMIT :limit"
    )
    fun observeRecentForProfile(profileId: Int, limit: Int = 50): Flow<List<DoseLog>>

    // Drives the live "next eligible" UI: the most recent dose of this medication for
    // this profile, if any.
    @Query(
        "SELECT * FROM dose_logs WHERE profileId = :profileId AND medicationId = :medicationId " +
            "ORDER BY givenAtEpochMillis DESC LIMIT 1"
    )
    fun observeMostRecentDose(profileId: Int, medicationId: Int): Flow<DoseLog?>

    // Snapshot read used headlessly by BootReminderReceiver to re-arm alarms.
    @Query(
        "SELECT * FROM dose_logs WHERE profileId = :profileId AND medicationId = :medicationId " +
            "ORDER BY givenAtEpochMillis DESC LIMIT 1"
    )
    suspend fun getMostRecentDoseSnapshot(profileId: Int, medicationId: Int): DoseLog?

    // All doses with a still-pending reminder, used to re-arm every alarm after reboot.
    @Query(
        "SELECT * FROM dose_logs WHERE nextEligibleAtEpochMillis IS NOT NULL " +
            "AND nextEligibleAtEpochMillis > :nowEpochMillis"
    )
    suspend fun getPendingReminders(nowEpochMillis: Long): List<DoseLog>

    // Plain insert, not a compare-and-set update: every dose log is an additive history
    // event, and near-simultaneous logs from two caregivers are exactly the data this
    // app is designed to capture and surface, not a race to resolve.
    @Insert
    suspend fun insert(doseLog: DoseLog): Long
}
